// Unified line diffs in plain JS: Myers' O(ND) algorithm over the lines left
// once the common head and tail are trimmed, then hunks with 3 lines of
// context. No dependencies, so it runs in the hooks environment as is.

export type Op = { t: ' ' | '-' | '+'; line: string }

export type Hunks = { hunks: string[]; added: number; removed: number }

const CONTEXT = 3
// Past this many edits the trace would cost too much memory: the changed
// middle is shown as all removed, then all added.
const MAX_D = 1500
// A hunk longer than this is split into several, each with its own header,
// so one paged view never has to hold a whole rewritten file.
const MAX_HUNK_LINES = 200
// A drawn line is cut here (minified files would swamp the pane).
const MAX_LINE_CHARS = 400

export function splitLines(text: string): string[] {
  if (text === '') return []
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines.map(line => (line.endsWith('\r') ? line.slice(0, -1) : line))
}

// The edit script turning a into b, or null when it needs more than maxD
// insertions and deletions.
function myers(a: string[], b: string[], maxD: number): Op[] | null {
  const n = a.length
  const m = b.length
  const limit = Math.min(n + m, maxD)
  const offset = limit + 1
  const v = new Int32Array(2 * limit + 3)
  const trace: Int32Array[] = []
  let found = -1

  outer: for (let d = 0; d <= limit; d++) {
    // v as it stood after step d-1, for k in [-d-1, d+1].
    trace.push(v.slice(offset - d - 1, offset + d + 2))
    for (let k = -d; k <= d; k += 2) {
      const down = k === -d || (k !== d && v[offset + k - 1]! < v[offset + k + 1]!)
      let x = down ? v[offset + k + 1]! : v[offset + k - 1]! + 1
      let y = x - k
      while (x < n && y < m && a[x] === b[y]) {
        x++
        y++
      }
      v[offset + k] = x
      if (x >= n && y >= m) {
        found = d
        break outer
      }
    }
  }
  if (found < 0) return null

  const ops: Op[] = []
  let x = n
  let y = m
  for (let d = found; d >= 0; d--) {
    const saved = trace[d]!
    const at = (k: number) => saved[k + d + 1]!
    const k = x - y
    const down = k === -d || (k !== d && at(k - 1) < at(k + 1))
    const prevK = down ? k + 1 : k - 1
    const prevX = d === 0 ? 0 : at(prevK)
    const prevY = prevX - prevK
    while (x > prevX && y > prevY) {
      ops.push({ t: ' ', line: a[--x]! })
      y--
    }
    if (d > 0) {
      if (x === prevX) ops.push({ t: '+', line: b[--y]! })
      else ops.push({ t: '-', line: a[--x]! })
    }
  }
  return ops.reverse()
}

export function diffLines(a: string[], b: string[]): Op[] {
  let head = 0
  while (head < a.length && head < b.length && a[head] === b[head]) head++
  let tail = 0
  while (
    tail < a.length - head &&
    tail < b.length - head &&
    a[a.length - 1 - tail] === b[b.length - 1 - tail]
  ) {
    tail++
  }
  const midA = a.slice(head, a.length - tail)
  const midB = b.slice(head, b.length - tail)
  const middle = myers(midA, midB, MAX_D) ?? [
    ...midA.map((line): Op => ({ t: '-', line })),
    ...midB.map((line): Op => ({ t: '+', line })),
  ]
  return [
    ...a.slice(0, head).map((line): Op => ({ t: ' ', line })),
    ...middle,
    ...a.slice(a.length - tail).map((line): Op => ({ t: ' ', line })),
  ]
}

type Numbered = Op & { o: number; n: number }

function header(ops: Numbered[]): string {
  const first = ops[0]!
  const oldCount = ops.filter(op => op.t !== '+').length
  const newCount = ops.filter(op => op.t !== '-').length
  const oldStart = oldCount > 0 ? first.o : first.o - 1
  const newStart = newCount > 0 ? first.n : first.n - 1
  return `@@ -${oldStart},${oldCount} +${newStart},${newCount} @@`
}

function cut(line: string): string {
  return line.length > MAX_LINE_CHARS ? `${line.slice(0, MAX_LINE_CHARS)}…` : line
}

// Hunk texts (header and body, no trailing newline) for the change from
// `before` to `after`, with CONTEXT lines around each change.
export function unifiedHunks(before: string, after: string): Hunks {
  const ops = diffLines(splitLines(before), splitLines(after))
  let o = 1
  let n = 1
  let added = 0
  let removed = 0
  const numbered: Numbered[] = ops.map(op => {
    const row = { ...op, o, n }
    if (op.t !== '+') o++
    if (op.t !== '-') n++
    if (op.t === '+') added++
    if (op.t === '-') removed++
    return row
  })

  const ranges: [number, number][] = []
  numbered.forEach((op, at) => {
    if (op.t === ' ') return
    const start = Math.max(0, at - CONTEXT)
    const end = Math.min(numbered.length - 1, at + CONTEXT)
    const last = ranges[ranges.length - 1]
    if (last && start <= last[1] + 1) last[1] = Math.max(last[1], end)
    else ranges.push([start, end])
  })

  const hunks: string[] = []
  for (const [start, end] of ranges) {
    const rows = numbered.slice(start, end + 1)
    for (let at = 0; at < rows.length; at += MAX_HUNK_LINES) {
      const part = rows.slice(at, at + MAX_HUNK_LINES)
      hunks.push([header(part), ...part.map(op => op.t + cut(op.line))].join('\n'))
    }
  }
  return { hunks, added, removed }
}

// Hunks a tool already computed (Edit's and Write's `structuredPatch`), as
// hunk texts with the same caps.
export function patchHunks(
  patch: readonly { oldStart: number; oldLines: number; newStart: number; newLines: number; lines: readonly string[] }[],
): Hunks {
  let added = 0
  let removed = 0
  const hunks = patch.map(part => {
    const lines = part.lines.filter(line => !line.startsWith('\\'))
    for (const line of lines) {
      if (line.startsWith('+')) added++
      else if (line.startsWith('-')) removed++
    }
    const head = `@@ -${part.oldStart},${part.oldLines} +${part.newStart},${part.newLines} @@`
    return [head, ...lines.map(line => line.slice(0, 1) + cut(line.slice(1)))].join('\n')
  })
  return { hunks, added, removed }
}

files.hooks/rows.ts:
// A file's stored hunks as the rows a GitHub-style view draws: numbered
// lines on both sides, the changed words of a reworded line, and the runs of
// unchanged lines between hunks. Pure, so tests read it directly.

import { diffLines } from './diff'

export type Span = { text: string; isChanged: boolean }

export type LineKind = 'context' | 'removed' | 'added'

export type Line = {
  kind: LineKind
  old?: number
  new?: number
  spans: Span[]
}

export type Gap = { kind: 'gap'; count: number; from: number }

// One row of the unified view: a line, or the unchanged lines skipped.
export type Row = Gap | Line

// One row of the split view: the old file's line beside the new file's.
export type SplitRow = Gap | { kind: 'pair'; left?: Line; right?: Line }

const HEADER = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/
// Reworded lines longer than this are marked whole.
const MAX_WORD_DIFF_TOKENS = 300
// Below this share of unchanged characters, word marks are noise.
const MIN_KEPT_SHARE = 0.4

const whole = (text: string): Span[] => [{ text, isChanged: false }]

function tokens(text: string): string[] {
  return text.match(/\w+|\s+|[^\w\s]/g) ?? []
}

function joined(parts: Span[]): Span[] {
  const spans: Span[] = []
  for (const part of parts) {
    const last = spans[spans.length - 1]
    if (last && last.isChanged === part.isChanged) last.text += part.text
    else spans.push({ ...part })
  }
  return spans
}

// The removed and added versions of a reworded line, each split into the
// words it shares with the other and the words that changed; null when the
// lines differ too much for word marks to help.
export function wordSpans(before: string, after: string): [Span[], Span[]] | null {
  const a = tokens(before)
  const b = tokens(after)
  if (a.length > MAX_WORD_DIFF_TOKENS || b.length > MAX_WORD_DIFF_TOKENS) return null
  const ops = diffLines(a, b)
  const kept = ops.filter(op => op.t === ' ').reduce((sum, op) => sum + op.line.length, 0)
  if (kept < MIN_KEPT_SHARE * Math.max(before.length, after.length)) return null
  const left = joined(ops.filter(op => op.t !== '+').map(op => ({ text: op.line, isChanged: op.t === '-' })))
  const right = joined(ops.filter(op => op.t !== '-').map(op => ({ text: op.line, isChanged: op.t === '+' })))
  return [left, right]
}

type Hunk = { firstOld: number; oldLines: number; lines: Line[] }

function parseHunk(text: string): Hunk | null {
  const [head = '', ...body] = text.split('\n')
  const match = HEADER.exec(head)
  if (match === null) return null
  const oldLines = match[2] === undefined ? 1 : Number(match[2])
  const newLines = match[4] === undefined ? 1 : Number(match[4])
  // A side with no lines names the line it comes after.
  const firstOld = Number(match[1]) + (oldLines === 0 ? 1 : 0)
  let old = firstOld
  let next = Number(match[3]) + (newLines === 0 ? 1 : 0)
  const lines: Line[] = []
  for (const raw of body) {
    const mark = raw.slice(0, 1)
    const line = raw.slice(1)
    if (mark === '-') lines.push({ kind: 'removed', old: old++, spans: whole(line) })
    else if (mark === '+') lines.push({ kind: 'added', new: next++, spans: whole(line) })
    else if (mark === ' ') lines.push({ kind: 'context', old: old++, new: next++, spans: whole(line) })
  }
  markWords(lines)
  return { firstOld, oldLines, lines }
}

// Pairs each run of removed lines with the added run right after it and
// marks the words that changed in each pair.
function markWords(lines: Line[]) {
  for (let at = 0; at < lines.length; ) {
    if (lines[at]!.kind !== 'removed') {
      at++
      continue
    }
    const removedFrom = at
    while (at < lines.length && lines[at]!.kind === 'removed') at++
    const addedFrom = at
    while (at < lines.length && lines[at]!.kind === 'added') at++
    const pairs = Math.min(addedFrom - removedFrom, at - addedFrom)
    for (let k = 0; k < pairs; k++) {
      const removed = lines[removedFrom + k]!
      const added = lines[addedFrom + k]!
      const spans = wordSpans(removed.spans[0]!.text, added.spans[0]!.text)
      if (spans !== null) [removed.spans, added.spans] = spans
    }
  }
}

// The unified rows of a file's hunks, a gap row wherever lines are skipped.
export function rowsOf(hunks: readonly string[]): Row[] {
  const rows: Row[] = []
  let nextOld = 1
  for (const text of hunks) {
    const hunk = parseHunk(text)
    if (hunk === null) continue
    if (hunk.firstOld > nextOld) rows.push({ kind: 'gap', count: hunk.firstOld - nextOld, from: nextOld })
    rows.push(...hunk.lines)
    nextOld = hunk.firstOld + hunk.oldLines
  }
  return rows
}

// The same rows side by side: unchanged lines on both sides, each removed
// run beside the added run that replaced it.
export function splitRowsOf(rows: readonly Row[]): SplitRow[] {
  const out: SplitRow[] = []
  for (let at = 0; at < rows.length; ) {
    const row = rows[at]!
    if (row.kind === 'gap') {
      out.push(row)
      at++
      continue
    }
    if (row.kind === 'context') {
      out.push({ kind: 'pair', left: row, right: row })
      at++
      continue
    }
    const removed: Line[] = []
    const added: Line[] = []
    for (let next = rows[at]; next?.kind === 'removed'; next = rows[++at]) removed.push(next)
    for (let next = rows[at]; next?.kind === 'added'; next = rows[++at]) added.push(next)
    for (let k = 0; k < Math.max(removed.length, added.length); k++) {
      const left = removed[k]
      const right = added[k]
      out.push({ kind: 'pair', ...(left ? { left } : {}), ...(right ? { right } : {}) })
    }
  }
  return out
}

// Text a surface may lay out as prose keeps its indentation and inner runs
// of spaces: tabs become spaces, and spaces that would collapse become
// no-break spaces (drawn the same in a terminal).
export function keepSpaces(text: string): string {
  return text
    .replace(/\t/g, '    ')
    .replace(/^ +/, lead => ' '.repeat(lead.length))
    .replace(/ {2,}/g, run => ' '.repeat(run.length - 1) + ' ')
}

files.hooks/svg.ts:
// A file's diff rows drawn as SVG pictures in GitHub's diff style: a 12px
// monospaced face on 20px rows, line numbers on tinted gutters, tinted rows,
// the changed words marked, and syntax colours. A surface whose Text has no
// monospaced face (the desktop's engine before 2.1.300 refuses `mono`) shows
// these through its Svg element. The tints are translucent and the text
// colours switch with `prefers-color-scheme`, so a light or a dark theme
// reads them. Pure, so tests read it directly.

import type { Line, LineKind, Row, SplitRow } from './rows'
import { languageOf, tokensOf } from './syntax'
import type { TokenClass } from './syntax'

// One cell of SF Mono or Menlo at 12px, the face's 0.6em advance.
export const CHAR_PX = 7.22
const ROW_PX = 20
const BASELINE_PX = 14
const NUMBER_PAD_PX = 8
// The +/- column before the code.
const SIGN_PX = 18
const RIGHT_PAD_PX = 8
// The fewest characters a wrapped line keeps, however narrow the pane.
const MIN_CHARS = 16
// One picture's markup stays under the Svg element's 131,072 characters.
const MAX_SOURCE_CHARS = 120_000

const STYLE =
  '<style>' +
  'text{font-family:ui-monospace,SFMono-Regular,"SF Mono",Menlo,Consolas,monospace;font-size:12px;white-space:pre;fill:#e6edf3}' +
  '.ra{fill:#2ea04326}.na{fill:#3fb9504d}.wa{fill:#2ea04366}' +
  '.rd{fill:#f8514926}.nd{fill:#f851494d}.wd{fill:#f8514966}' +
  '.rh{fill:#388bfd1a}.nh{fill:#388bfd33}.re{fill:#6e76811a}.sep{fill:#6e768166}' +
  '.n{fill:#6e7681}.m{fill:#8b949e}' +
  '.keyword{fill:#ff7b72}.string{fill:#a5d6ff}.comment{fill:#8b949e}.constant{fill:#79c0ff}.function{fill:#d2a8ff}.type{fill:#ffa657}' +
  '@media (prefers-color-scheme:light){text{fill:#1f2328}.n,.m,.comment{fill:#59636e}' +
  '.keyword{fill:#cf222e}.string{fill:#0a3069}.constant{fill:#0550ae}.function{fill:#6639ba}.type{fill:#953800}}' +
  '</style>'

const ROW_CLASS: Record<LineKind, string | undefined> = { context: undefined, removed: 'rd', added: 'ra' }
const NUMBER_CLASS: Record<LineKind, string | undefined> = { context: undefined, removed: 'nd', added: 'na' }
const WORD_CLASS: Record<LineKind, string | undefined> = { context: undefined, removed: 'wd', added: 'wa' }
const SIGN: Record<LineKind, string> = { context: '', removed: '−', added: '+' }

export type DiffPicture = { source: string; width: number; height: number }

export type PictureOptions = {
  // The picture's width in CSS pixels.
  width: number
  // Long lines continue on the rows below; else they are cut with an ellipsis.
  wrap: boolean
  // The file's path, which names its language.
  path: string
  // Digits of the largest line number.
  digits: number
  // Old lines beside new ones; else interleaved.
  isSplit: boolean
  // A new file has no old line numbers to show.
  isNew: boolean
}

type Run = { text: string; at: number; isChanged: boolean; kind: TokenClass | undefined }

// A side of the picture, in its own viewport: the whole picture unified,
// one half of it split. `chars` is how many characters a row holds.
type Side = { numberWidth: number; numbers: number; codeX: number; chars: number }

const px = (n: number) => String(Math.round(n * 10) / 10)

const escape = (text: string) => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')

// Characters XML refuses, lone surrogates among them, drawn as U+FFFD.
const clean = (text: string) =>
  text.replace(
    /[\u0000-\u0008\u000b\u000c\u000e-\u001f￾￿]|[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/g,
    '�',
  )

function sideOf(width: number, numbers: number, digits: number): Side {
  const numberWidth = digits * CHAR_PX + 2 * NUMBER_PAD_PX
  const codeX = numbers * numberWidth + SIGN_PX
  const chars = Math.max(MIN_CHARS, Math.floor((width - codeX - RIGHT_PAD_PX) / CHAR_PX))
  return { numberWidth, numbers, codeX, chars }
}

// A line's text with tabs as four spaces, each character marked changed or
// not and with its syntax class, then cut into the rows it is drawn on.
function rowsOfLine(line: Line, side: Side, wrap: boolean, language: ReturnType<typeof languageOf>): Run[][] {
  let text = ''
  const changed: boolean[] = []
  for (const span of line.spans) {
    const part = clean(span.text.replace(/\t/g, '    ').replace(/\r/g, ''))
    text += part
    for (let k = 0; k < part.length; k++) changed.push(span.isChanged)
  }
  const kinds: (TokenClass | undefined)[] = new Array(text.length).fill(undefined)
  for (const token of tokensOf(text, language)) kinds.fill(token.kind, token.from, token.to)

  const cuts: [number, number][] = []
  if (!wrap || text.length <= side.chars) {
    cuts.push([0, Math.min(text.length, wrap ? text.length : side.chars)])
  } else {
    for (let from = 0; from < text.length; ) {
      let to = Math.min(text.length, from + side.chars)
      if (to < text.length) {
        // After the row's last space, as text wraps, unless that leaves
        // the row less than half full.
        const space = text.lastIndexOf(' ', to - 1)
        if (space >= from + side.chars / 2) to = space + 1
        // Never between the two halves of a surrogate pair.
        else if (/[\ud800-\udbff]/.test(text[to - 1]!)) to--
      }
      cuts.push([from, to])
      from = to
    }
  }

  const rows = cuts.map(([from, to]) => {
    const runs: Run[] = []
    for (let at = from; at < to; at++) {
      const last = runs[runs.length - 1]
      if (last !== undefined && last.isChanged === changed[at] && last.kind === kinds[at]) last.text += text[at]
      else runs.push({ text: text[at]!, at: at - from, isChanged: changed[at]!, kind: kinds[at] })
    }
    return runs
  })
  if (!wrap && text.length > side.chars) {
    const runs = rows[0]!
    const last = runs[runs.length - 1]
    if (last !== undefined) last.text = last.text.slice(0, -1)
    runs.push({ text: '…', at: side.chars - 1, isChanged: false, kind: 'comment' })
  }
  return rows
}

// A rectangle; a width given as a string is a share of the viewport ("100%").
function rect(className: string, x: number, y: number, width: number | string, height: number) {
  const across = typeof width === 'string' ? width : px(width)
  return `<rect class="${className}" x="${px(x)}" y="${px(y)}" width="${across}" height="${px(height)}"/>`
}

// One side of one row: its tints, line numbers, sign and code.
function lineMarkup(
  side: Side,
  line: Line,
  numbers: (number | undefined)[],
  rows: Run[][],
  y: number,
  height: number,
): string {
  let out = ''
  const rowClass = ROW_CLASS[line.kind]
  const numberClass = NUMBER_CLASS[line.kind]
  const wordClass = WORD_CLASS[line.kind]
  if (rowClass !== undefined) out += rect(rowClass, 0, y, '100%', height)
  if (numberClass !== undefined) out += rect(numberClass, 0, y, side.numbers * side.numberWidth, height)
  const base = y + BASELINE_PX
  numbers.forEach((n, k) => {
    if (n === undefined) return
    const right = (k + 1) * side.numberWidth - NUMBER_PAD_PX
    out += `<text class="n" x="${px(right)}" y="${px(base)}" text-anchor="end">${n}</text>`
  })
  const sign = SIGN[line.kind]
  if (sign !== '') out += `<text x="${px(side.codeX - SIGN_PX + 5)}" y="${px(base)}">${sign}</text>`
  rows.forEach((runs, k) => {
    const top = y + k * ROW_PX
    if (wordClass !== undefined) {
      for (const run of runs) {
        if (!run.isChanged || run.text.trim() === '') continue
        out += `<rect class="${wordClass}" x="${px(side.codeX + run.at * CHAR_PX)}" y="${px(top + 1)}" width="${px(run.text.length * CHAR_PX)}" height="${ROW_PX - 2}" rx="2"/>`
      }
    }
    const spans = runs
      .filter(run => run.text !== '')
      .map(run => {
        const kind = run.kind !== undefined ? ` class="${run.kind}"` : ''
        return `<tspan x="${px(side.codeX + run.at * CHAR_PX)}"${kind}>${escape(run.text)}</tspan>`
      })
      .join('')
    if (spans !== '') out += `<text y="${px(top + BASELINE_PX)}">${spans}</text>`
  })
  return out
}

function gapMarkup(gap: Extract<Row, { kind: 'gap' }>, side: Side, y: number): string {
  const where = gap.count === 1 ? `line ${gap.from}` : `lines ${gap.from}–${gap.from + gap.count - 1}`
  const label = `⋯ ${gap.count} unchanged line${gap.count === 1 ? '' : 's'} (${where})`
  return (
    rect('rh', 0, y, '100%', ROW_PX) +
    rect('nh', 0, y, side.numbers * side.numberWidth, ROW_PX) +
    `<text class="m" x="${px(side.codeX - SIGN_PX + 5)}" y="${px(y + BASELINE_PX)}">${escape(label)}</text>`
  )
}

// The rows of one file (one page of them) as pictures, each under the
// element's size: one, unless the page is very long. A picture is as wide
// as the room it is drawn in, its tints drawn across it at 1:1; `width`,
// what the room is thought to be, only decides where long lines wrap.
export function diffPictures(rows: readonly (Row | SplitRow)[], options: PictureOptions): DiffPicture[] {
  const width = Math.max(200, Math.floor(options.width))
  const language = languageOf(options.path)
  const unified = sideOf(width, options.isNew ? 1 : 2, options.digits)
  const half = sideOf(width / 2, 1, options.digits)

  const pictures: DiffPicture[] = []
  // Unified, everything is drawn in `body`; split, the gaps are, and each
  // half's lines in a viewport of its own, which clips them at the middle.
  let body = ''
  let left = ''
  let right = ''
  let height = 0
  const close = () => {
    if (height === 0) return
    const halves = options.isSplit
      ? `<svg width="50%" height="${height}">${left}</svg>` +
        `<svg x="50%" width="50%" height="${height}">${right}</svg>` +
        `<rect class="sep" x="50%" y="0" width="1" height="${height}"/>`
      : ''
    pictures.push({
      source:
        `<svg xmlns="http://www.w3.org/2000/svg" xml:space="preserve" width="100%" height="${height}">` +
        STYLE +
        body +
        halves +
        '</svg>',
      width,
      height,
    })
    body = left = right = ''
    height = 0
  }

  for (const row of rows) {
    // The row's markup at `y`: for the whole picture, the left and the right half.
    const draw = (y: number): [string, string, string, number] => {
      if (row.kind === 'gap') return [gapMarkup(row, options.isSplit ? half : unified, y), '', '', ROW_PX]
      if (row.kind === 'pair') {
        const leftRows = row.left !== undefined ? rowsOfLine(row.left, half, options.wrap, language) : []
        const rightRows = row.right !== undefined ? rowsOfLine(row.right, half, options.wrap, language) : []
        const tall = Math.max(1, leftRows.length, rightRows.length) * ROW_PX
        const one = (line: Line | undefined, lines: Run[][], number: number | undefined) =>
          line === undefined ? rect('re', 0, y, '100%', tall) : lineMarkup(half, line, [number], lines, y, tall)
        return ['', one(row.left, leftRows, row.left?.old), one(row.right, rightRows, row.right?.new), tall]
      }
      const lines = rowsOfLine(row, unified, options.wrap, language)
      const tall = Math.max(1, lines.length) * ROW_PX
      const numbers = options.isNew ? [row.new] : [row.old, row.new]
      return [lineMarkup(unified, row, numbers, lines, y, tall), '', '', tall]
    }
    let drawn = draw(height)
    const size = drawn[0].length + drawn[1].length + drawn[2].length
    if (height > 0 && body.length + left.length + right.length + size > MAX_SOURCE_CHARS) {
      close()
      drawn = draw(0)
    }
    body += drawn[0]
    left += drawn[1]
    right += drawn[2]
    height += drawn[3]
  }
  close()
  return pictures
}

files.hooks/syntax.ts:
// A small line-at-a-time highlighter for the diff picture: keywords,
// strings, comments, numbers and constants, function and type names. It
// knows a handful of language families by file extension and reads each
// line on its own, so a string or comment spanning lines is only guessed.

export type TokenClass = 'keyword' | 'string' | 'comment' | 'constant' | 'function' | 'type'

export type Token = { from: number; to: number; kind: TokenClass }

type Language = {
  keywords: ReadonlySet<string>
  constants: ReadonlySet<string>
  lineComments: readonly string[]
  blockComment?: readonly [string, string]
  quotes: string
  isCaseBlind?: boolean
}

const words = (text: string): ReadonlySet<string> => new Set(text.split(/\s+/).filter(Boolean))

// A keyword that names what the next word declares.
const NAMES_TYPE = words('class interface type struct enum trait impl union module namespace')
const NAMES_FUNCTION = words('function def func fn fun')

const C_LIKE: Language = {
  keywords: words(`abstract as async await break case catch chan char class const continue
    debugger declare default defer delete do double else enum export extends extern final finally
    float fn for from func function go goto if impl implements import in instanceof int interface is
    keyof let long loop map match mod move mut namespace new of override package private protected
    pub public range readonly return satisfies select short signed sizeof static struct super switch
    this throw throws trait try type typedef typeof union unsafe unsigned use using var virtual void
    volatile when where while with yield val fun object sealed data open lateinit`),
  constants: words('true false null nil undefined NaN Infinity None Some Ok Err self Self iota'),
  lineComments: ['//'],
  blockComment: ['/*', '*/'],
  quotes: `'"\``,
}

const PYTHON: Language = {
  keywords: words(`and as assert async await break class continue def del elif else except
    finally for from global if import in is lambda nonlocal not or pass raise return try while with
    yield match case print`),
  constants: words('True False None self cls'),
  lineComments: ['#'],
  quotes: `'"`,
}

const SHELL: Language = {
  keywords: words(`if then else elif fi for while until do done case esac function in return local
    export readonly declare source echo exit set unset shift`),
  constants: words('true false'),
  lineComments: ['#'],
  quotes: `'"\``,
}

const RUBY: Language = {
  keywords: words(`def end if elsif else unless while until for in do return class module begin
    rescue ensure require require_relative yield then case when attr_reader attr_accessor private`),
  constants: words('nil true false self'),
  lineComments: ['#'],
  quotes: `'"`,
}

const DATA: Language = {
  keywords: words(''),
  constants: words('true false null yes no on off'),
  lineComments: ['#'],
  quotes: `'"`,
}

const JSON_LIKE: Language = { ...DATA, lineComments: [] }

const CSS: Language = {
  keywords: words('import media supports keyframes font-face from to important'),
  constants: words(''),
  lineComments: [],
  blockComment: ['/*', '*/'],
  quotes: `'"`,
}

const SQL: Language = {
  keywords: words(`select from where join left right inner outer on and or not insert into values
    update set delete create table alter drop index primary key foreign references as group by
    order having limit offset distinct union all case when then else end begin commit rollback
    with returning if exists`),
  constants: words('null true false'),
  lineComments: ['--'],
  blockComment: ['/*', '*/'],
  quotes: `'"`,
  isCaseBlind: true,
}

const BY_EXTENSION: Record<string, Language> = {
  ts: C_LIKE, tsx: C_LIKE, mts: C_LIKE, cts: C_LIKE, js: C_LIKE, jsx: C_LIKE, mjs: C_LIKE, cjs: C_LIKE,
  go: C_LIKE, rs: C_LIKE, java: C_LIKE, kt: C_LIKE, kts: C_LIKE, scala: C_LIKE, swift: C_LIKE,
  c: C_LIKE, h: C_LIKE, cc: C_LIKE, cpp: C_LIKE, hpp: C_LIKE, cs: C_LIKE, dart: C_LIKE, php: C_LIKE,
  py: PYTHON, pyi: PYTHON,
  sh: SHELL, bash: SHELL, zsh: SHELL, fish: SHELL,
  rb: RUBY, rake: RUBY,
  yml: DATA, yaml: DATA, toml: DATA, ini: DATA, cfg: DATA, conf: DATA, env: DATA,
  json: JSON_LIKE, jsonc: C_LIKE, json5: C_LIKE,
  css: CSS, scss: { ...CSS, lineComments: ['//'] }, less: { ...CSS, lineComments: ['//'] },
  sql: SQL,
}

const BY_NAME: Record<string, Language> = {
  Dockerfile: SHELL, Makefile: SHELL, Gemfile: RUBY, Rakefile: RUBY, '.bashrc': SHELL, '.zshrc': SHELL,
}

export function languageOf(path: string): Language | undefined {
  const name = path.slice(path.lastIndexOf('/') + 1).replace(/#.*$/, '')
  const byName = BY_NAME[name]
  if (byName !== undefined) return byName
  const dot = name.lastIndexOf('.')
  return dot < 0 ? undefined : BY_EXTENSION[name.slice(dot + 1).toLowerCase()]
}

const isWordStart = (ch: string) => /[A-Za-z_$]/.test(ch)
const isWord = (ch: string) => /[\w$]/.test(ch)

// The tokens of one line, in order, none overlapping.
export function tokensOf(text: string, language: Language | undefined): Token[] {
  if (language === undefined) return []
  const tokens: Token[] = []
  const trimmed = text.trimStart()
  // A line inside a block comment, as most code writes one.
  if (language.blockComment !== undefined && /^(\*|\/\*|\*\/)/.test(trimmed)) {
    return [{ from: text.length - trimmed.length, to: text.length, kind: 'comment' }]
  }
  let names: TokenClass | undefined
  let at = 0
  while (at < text.length) {
    const ch = text[at]!
    const block = language.blockComment
    if (block !== undefined && text.startsWith(block[0], at)) {
      const end = text.indexOf(block[1], at + block[0].length)
      const to = end < 0 ? text.length : end + block[1].length
      tokens.push({ from: at, to, kind: 'comment' })
      at = to
      continue
    }
    if (language.lineComments.some(mark => text.startsWith(mark, at) && (mark !== '#' || at === 0 || /\s/.test(text[at - 1]!)))) {
      tokens.push({ from: at, to: text.length, kind: 'comment' })
      break
    }
    if (language.quotes.includes(ch)) {
      let to = at + 1
      while (to < text.length && text[to] !== ch) to += text[to] === '\\' ? 2 : 1
      to = Math.min(text.length, to + 1)
      tokens.push({ from: at, to, kind: 'string' })
      at = to
      continue
    }
    if (/\d/.test(ch) && (at === 0 || !isWord(text[at - 1]!))) {
      const match = /^(0[xX][\da-fA-F_]+|\d[\d_]*(\.\d+)?([eE][+-]?\d+)?)/.exec(text.slice(at))
      const to = at + (match?.[0].length ?? 1)
      tokens.push({ from: at, to, kind: 'constant' })
      at = to
      continue
    }
    if (isWordStart(ch)) {
      let to = at + 1
      while (to < text.length && isWord(text[to]!)) to++
      const word = text.slice(at, to)
      const key = language.isCaseBlind ? word.toLowerCase() : word
      let next = to
      while (next < text.length && text[next] === ' ') next++
      if (language.keywords.has(key)) {
        tokens.push({ from: at, to, kind: 'keyword' })
        names = NAMES_TYPE.has(key) ? 'type' : NAMES_FUNCTION.has(key) ? 'function' : undefined
      } else if (language.constants.has(key)) {
        tokens.push({ from: at, to, kind: 'constant' })
        names = undefined
      } else if (names !== undefined) {
        tokens.push({ from: at, to, kind: names })
        names = undefined
      } else if (text[next] === '(') {
        tokens.push({ from: at, to, kind: 'function' })
      }
      at = to
      continue
    }
    at++
  }
  return tokens
}

